import ProjectDescription

// Tuist configuration for Shpora.
//
// `fullHandle` binds this repo to its tuist.dev project so Build Insights
// (https://tuist.dev/alexey1312/shpora) has somewhere to upload metrics. Once a
// handle is set, `tuist generate` injects the `tuist inspect build` post-action
// into every auto-generated scheme (we declare no explicit `schemes:` in
// Project.swift, so all schemes are auto-generated). Build locally or on CI while
// logged in (`tuist auth login`) and timings show up in the dashboard.
//
// Tuist version stays pinned (mise → 4.195.16) so local and CI generation read
// the same ProjectDescription. The SPM graph comes from Tuist/Package.swift via
// `tuist install`.
let tuist = Tuist(
    fullHandle: "alexey1312/shpora",
    project: .tuist(
        generationOptions: .options(
            // Keep standard Debug/Release configs (vanilla) so TCA macros build
            // as native XcodeProj targets without "Trust & Enable" friction.
            disablePackageVersionLocking: false,
            // Don't hard-require a Tuist token: `tuist generate` must keep working
            // offline / for unauthenticated CI. Insights upload only when logged in
            // (`tuist auth login`); the inspect-build post-action is injected
            // regardless, since it's gated on `fullHandle`, not on the session.
            optionalAuthentication: true,
            // Build Insights post-action OFF to drop its per-build overhead.
            // NOTE: this toggle is GLOBAL — committing it also stops CI insights
            // (Tuist has no Debug-local-only scope for the inspect-build post-action).
            buildInsightsDisabled: true,
            // Xcode Cache on: compiled modules are reused via the local cache
            // daemon (`tuist setup cache`, socket under ~/.local/state/tuist).
            enableCaching: true,
        ),
    ),
)
